const DF_CFG={url:'https://tikjmiyrhkcjrxjylmqb.supabase.co',key:'sb_publishable_clr5P9USk7b63MajJmmr9A_Iz0wi_0F',version:'2026.08.16-defect-focus1'};
const DF_SESSION='fleet_mvp_session_v2';
function dfSession(){try{return JSON.parse(localStorage.getItem(DF_SESSION)||'null')}catch{return null}}
function dfSave(s){if(s)localStorage.setItem(DF_SESSION,JSON.stringify(s))}
async function dfRefresh(){const s=dfSession();if(!s?.refresh_token)throw new Error('Сессия истекла.');const r=await fetch(`${DF_CFG.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:DF_CFG.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.access_token)throw new Error(d.message||d.msg||'Сессия истекла.');d.obtained_at=Date.now();dfSave(d);return d}
async function dfRpc(name,params={},retry=true){let s=dfSession();if(!s?.access_token)return null;try{let r=await fetch(`${DF_CFG.url}/rest/v1/rpc/${encodeURIComponent(name)}`,{method:'POST',headers:{apikey:DF_CFG.key,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(params)});if(r.status===401&&retry){s=await dfRefresh();r=await fetch(`${DF_CFG.url}/rest/v1/rpc/${encodeURIComponent(name)}`,{method:'POST',headers:{apikey:DF_CFG.key,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(params)})}if(!r.ok)return null;const t=await r.text();return t?JSON.parse(t):null}catch{return null}}
function dfEsc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
async function dfDecorate(backdrop){if(!backdrop||backdrop.dataset.df===DF_CFG.version)return;const btn=backdrop.querySelector('[data-svc-defect-action][data-id]');if(!btn)return;backdrop.dataset.df='loading';const card=await dfRpc('get_defect_card',{p_defect_id:btn.dataset.id});if(!card||!document.body.contains(backdrop)){delete backdrop.dataset.df;return}const severity=backdrop.querySelector('.svc-severity');if(severity){const label=severity.querySelector('span'),value=severity.querySelector('strong');if(label)label.textContent='Можно продолжать?';if(value)value.textContent=card.severity_label||'Нужна проверка'}const row=backdrop.querySelector('.action-row');if(row&&!backdrop.querySelector('.df-next')){const ns=card.next_step||{};const note=document.createElement('div');note.className='demo-note df-next';note.innerHTML=`<strong>${dfEsc(ns.title||'Следующий шаг')}</strong>${ns.detail?`<div>${dfEsc(ns.detail)}</div>`:''}`;row.insertAdjacentElement('beforebegin',note)}backdrop.dataset.df=DF_CFG.version}
let dfBackdrop=null;new MutationObserver(()=>{const b=document.querySelector('.svc-backdrop');if(b!==dfBackdrop){dfBackdrop=b;if(b)queueMicrotask(()=>dfDecorate(b))}}).observe(document.documentElement,{childList:true,subtree:true});
